import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Codified Context: Infrastructure for AI Agents in a Complex Codebase","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.20478","title":"Codified Context: Infrastructure for AI Agents in a Complex Codebase","arxiv_id":2602.20478,"collected_at":"2026-08-03T00:00:00.000Z","collected_by":"routine-d","domain":"Context Engineering","pdf_path":"pdfs/2602.20478.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-02-24-codified-context-infrastructure-ai-agents-2602-20478.md","filePath":"research/papers/2026-02-24-codified-context-infrastructure-ai-agents-2602-20478.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-02-24-codified-context-infrastructure-ai-agents-2602-20478.md"};function n(i,e,d,c,f,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="codified-context-infrastructure-for-ai-agents-in-a-complex-codebase" tabindex="-1">Codified Context: Infrastructure for AI Agents in a Complex Codebase <a class="header-anchor" href="#codified-context-infrastructure-for-ai-agents-in-a-complex-codebase" aria-label="Permalink to &quot;Codified Context: Infrastructure for AI Agents in a Complex Codebase&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>LLM-based 程式協作助理難以跨 session 維持記憶，經常遺失專案慣例並重複犯錯。本文針對一個 10.8 萬行的大型 C# 分散式系統，提出三段式基礎設施框架：(1) 「hot-memory constitution」 收錄慣例與檢索協定，(2) 十九個專職 domain-expert agent，(3) 「cold-memory knowledge base」 內含三十四份可依需求調閱的規格文件。論文分析 283 次開發 session 的指標，並以四個案例研究 展示 codified context 如何在各自獨立的工作 session 間維持一致性、避免失誤重演。該框架已 開源並附文件。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>本文的 hot-memory constitution / cold-memory knowledge base 二分，與本 workspace CLAUDE.md（穩定前綴、auto-load）+ <code>.claude/refs/</code>（按需讀取）的 progressive disclosure 架構高度同構，等於是「codified context」設計在另一個大型 codebase 上的獨立驗證；其 283-session 實測數據為本庫「結構性下沉優先於壓縮」的設計選擇提供外部佐證。</p>',5)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
